// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address logAddr, uint256 amount, uint256 lockTime) public {
        vm.assume(logAddr != address(0));
        vm.assume(uint160(logAddr) > 100); // avoid precompiles
        amount = bound(amount, 1 ether, 100 ether);
        lockTime = bound(lockTime, 0, 365 days);

        address actor = address(0xBEEF);
        // deploy a real Log-compatible receiver at the fuzzed routing: we use a helper
        LogHelper log = new LogHelper();
        logAddr = address(log);

        vm.prank(actor);
        c.SetLogFile(logAddr);
        vm.deal(actor, amount);

        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

contract LogHelper {
    function AddMessage(address, uint256, string calldata) external pure {}
    fallback() external payable {}
    receive() external payable {}
}
